rows = [("A", " Food ", "150"), ("B", "books", "bad"), ("A", "food", "200")]
clean, rejected, seen = [], [], set()
for expense_id, category, raw_cents in rows:
    try:
        cents = int(raw_cents)
    except ValueError:
        rejected.append((expense_id, "invalid amount"))
        continue
    category = category.strip().lower()
    if not expense_id.strip() or not category or cents < 0:
        rejected.append((expense_id, "invalid record"))
    elif expense_id in seen:
        rejected.append((expense_id, "duplicate"))
    else:
        seen.add(expense_id)
        clean.append((expense_id, category, cents))
print(clean)
print(rejected)

def clean_cents(raw):
    cents = int(raw)
    if cents < 0:
        raise ValueError("negative cents")
    return cents

assert clean_cents("0") == 0
try:
    clean_cents("-1")
except ValueError:
    print("Negative rejected")
else:
    raise AssertionError("Negative cents should be rejected")

